package com.vandorlabs.neoforge.gear;

import java.util.*;
import net.minecraft.core.*;
import net.minecraft.core.component.DataComponents;
import net.minecraft.nbt.*;
import net.minecraft.server.level.*;
import net.minecraft.world.InteractionHand;
import net.minecraft.world.item.*;
import net.minecraft.world.item.component.CustomData;
import net.minecraft.world.level.GameType;
import net.minecraft.world.level.block.*;
import net.minecraft.world.level.block.entity.ChestBlockEntity;
import net.minecraft.world.phys.*;
import net.neoforged.bus.api.SubscribeEvent;
import net.neoforged.fml.common.EventBusSubscriber;
import net.neoforged.neoforge.event.server.ServerStartedEvent;
import net.neoforged.neoforge.event.tick.ServerTickEvent;

/** Horizontal Extenders push only contacted ordinary blocks, using actual ticks and durable ownership. */
@EventBusSubscriber(modid="vandorlabs")
public final class NativeGearPushChecks {
    private record Scene(BlockPos anchor,Direction mount,NativeGearDefinition kind,int layout) {
        BlockPos local(int x,int y,int z){return anchor.offset(NativeGearOrientation.vector(mount,new BlockPos(x,y,z)));}
        List<BlockPos> columns(){var result=new ArrayList<BlockPos>();for(int x:new int[]{0,2})for(int z:layout==2?new int[]{0,2}:new int[]{0})if(layout!=0||x==0)result.add(local(x,0,z));return result.stream().sorted().toList();}
        BlockPos root(){return columns().getFirst();}
        List<BlockPos> platform(int y){var result=new ArrayList<BlockPos>();for(int x=0;x<=(layout==0?0:2);x++)for(int z=0;z<=(layout==2?2:0);z++)result.add(local(x,y,z));return result;}
        BlockPos contact(int y){return local(layout==0?0:1,y,layout==2?1:0);}
        int firstContact(){return layout==0?-4:-3;}
    }
    private static final List<Scene> SCENES=new ArrayList<>();private static final int[] STAGES=new int[24];
    private static boolean lateObstruction,protectionProbe;
    private static ServerLevel world;private static Actor actor;private static boolean running;private static int ticks,checks;
    private static final class Actor extends net.neoforged.neoforge.common.util.FakePlayer {Actor(ServerLevel level){super(level,new com.mojang.authlib.GameProfile(new UUID(0,2211491),"NativeArmPush"));}}
    private static String phase(){return System.getProperty("vandorlabs.gearPushPhase","");}
    private static void need(boolean ok,String why){checks++;if(!ok)throw new AssertionError("Native push tick="+ticks+": "+why);}
    private static NativeGearEntity root(Scene scene){var root=NativeGearFormation.at(world,scene.root());need(root!=null&&!root.inert(),"healthy root "+scene);return root;}
    private static void position(Scene scene){actor.setPos(scene.root().getX()+.5,scene.root().getY()+5,scene.root().getZ()+.5);}
    private static void click(Scene scene){position(scene);actor.setItemInHand(InteractionHand.MAIN_HAND,ItemStack.EMPTY);need(actor.gameMode.useItemOn(actor,world,ItemStack.EMPTY,InteractionHand.MAIN_HAND,new BlockHitResult(Vec3.atCenterOf(scene.root()).add(0,0,-.5),Direction.NORTH,scene.root(),false)).consumesAction(),"ordinary manual interaction "+scene);}
    private static void retry(Scene scene){if(root(scene).target())click(scene);click(scene);}
    private static void scenes(){int n=0;for(int layout=0;layout<3;layout++)for(var kind:new NativeGearDefinition[]{NativeGearDefinition.EXTENDER,NativeGearDefinition.LARGE_EXTENDER})for(var mount:Direction.Plane.HORIZONTAL){SCENES.add(new Scene(new BlockPos(40000+n%8*32,110,40000+n/8*32),mount,kind,layout));n++;}need(SCENES.size()==24,"four horizontal faces, both sizes and three layouts");}
    private static void place(Scene scene,BlockPos at){position(scene);world.setBlock(at.relative(scene.mount.getOpposite()),Blocks.STONE.defaultBlockState(),3);var choices=NativeGearSettings.defaults().choices();choices.putBoolean("JoinArms",scene.layout!=0);choices.putInt("JoinRange",4);var data=new CompoundTag();data.put(NativeGearItem.SETTINGS,choices);var stack=new ItemStack(NativeGearBindings.ITEMS.get(scene.kind.id),4);stack.set(DataComponents.CUSTOM_DATA,CustomData.of(data));actor.setItemInHand(InteractionHand.MAIN_HAND,stack);for(int n=0;n<4;n++){var support=at.relative(scene.mount,n-1);need(actor.gameMode.useItemOn(actor,world,stack,InteractionHand.MAIN_HAND,new BlockHitResult(Vec3.atCenterOf(support).add(Vec3.atLowerCornerOf(scene.mount.getNormal()).scale(.5)),scene.mount,support,false)).consumesAction(),"ordinary Survival section "+scene+" part="+n);}need(stack.isEmpty(),"four sections consumed");}
    @SubscribeEvent public static void started(ServerStartedEvent event){if(phase().isEmpty())return;try{world=event.getServer().overworld();actor=new Actor(world);actor.setGameMode(GameType.SURVIVAL);scenes();for(var scene:SCENES)for(int x=-1;x<=1;x++)for(int z=-1;z<=1;z++){int cx=(scene.anchor.getX()>>4)+x,cz=(scene.anchor.getZ()>>4)+z;world.setChunkForced(cx,cz,true);world.getChunk(cx,cz);}if(phase().equals("read")){for(var scene:SCENES){var root=root(scene);need(root.progress()==0&&root.settings().pushBlocks()&&root.payload()!=null&&root.payload().materialized()&&root.hasStoredSections(),"saved retracted native payload with pushing "+scene);for(var at:scene.platform(-1))need(world.getBlockState(at).is(Blocks.STONE_BRICKS),"saved original layer "+at);need(world.getBlockState(scene.contact(-5)).is(Blocks.GOLD_BLOCK),"saved pushed block remains at contact destination");}finish("read");return;}for(var scene:SCENES){for(int x=-7;x<=7;x++)for(int y=-7;y<=7;y++)for(int z=-7;z<=7;z++)world.setBlock(scene.anchor.offset(x,y,z),Blocks.AIR.defaultBlockState(),18);for(var at:scene.columns())place(scene,at);}running=true;}catch(Throwable failure){fail(failure);}}
    @SubscribeEvent public static void tick(ServerTickEvent.Post event){if(!running)return;try{need(++ticks<2300,"timeout stages="+Arrays.toString(STAGES)+" first="+root(SCENES.getFirst()).error()+" phase="+root(SCENES.getFirst()).progress()+" target="+root(SCENES.getFirst()).target());boolean all=true;for(int index=0;index<SCENES.size();index++){var scene=SCENES.get(index);var root=root(scene);int stage=STAGES[index];if(stage==7)continue;all=false;
        if(stage==0){if(!root.controller()||root.columns().size()!=scene.columns().size())continue;for(var at:scene.platform(-4))world.setBlock(at,Blocks.STONE_BRICKS.defaultBlockState(),3);click(scene);STAGES[index]=1;continue;}
        if(stage==1){need(!root.blocked(),"initial retraction "+scene+" "+root.error());if(root.progress()!=0||NativeGearJournal.busy(root)||root.payload()==null||!root.payload().materialized())continue;var settings=root.settings().choices();settings.putBoolean("PushBlocks",true);position(scene);root.authorize(actor);need(root.configure(NativeGearSettings.readChoices(settings),false),"enable push at native retracted endpoint "+scene);world.setBlock(scene.contact(scene.firstContact()),Blocks.GOLD_BLOCK.defaultBlockState(),3);world.setBlock(scene.contact(-5),Blocks.BEDROCK.defaultBlockState(),3);click(scene);STAGES[index]=2;continue;}
        if(stage==2){if(!root.blocked())continue;need(root.progress()==0&&!NativeGearJournal.busy(root)&&root.payload().materialized(),"late immovable obstruction refuses before source removal "+scene+" "+root.error());for(var at:scene.platform(-1))need(world.getBlockState(at).is(Blocks.STONE_BRICKS),"refused original source retained "+at);need(world.getBlockState(scene.contact(scene.firstContact())).is(Blocks.GOLD_BLOCK),"refused contacted block retained");world.setBlock(scene.contact(-5),Blocks.AIR.defaultBlockState(),3);if(index==0){for(int distance=-scene.firstContact();distance<-scene.firstContact()+13;distance++)world.setBlock(scene.contact(-distance),Blocks.GOLD_BLOCK.defaultBlockState(),3);click(scene);boolean bounded=false;try{NativeGearPushing.preflight(root);}catch(IllegalArgumentException refused){bounded=true;}need(bounded&&root.payload().materialized(),"thirteen-block contact chain refuses before ownership changes");for(int distance=-scene.firstContact()+1;distance<-scene.firstContact()+13;distance++)world.setBlock(scene.contact(-distance),Blocks.AIR.defaultBlockState(),3);world.setBlock(scene.contact(-5),Blocks.CHEST.defaultBlockState(),3);((ChestBlockEntity)world.getBlockEntity(scene.contact(-5))).setItem(0,new ItemStack(Items.DIAMOND,3));retry(scene);STAGES[index]=3;}else{retry(scene);STAGES[index]=4;}continue;}
        if(stage==3){if(!root.blocked())continue;need(root.progress()==0&&root.payload().materialized()&&!NativeGearJournal.busy(root),"tile path refuses before capture");need(world.getBlockEntity(scene.contact(-5)) instanceof ChestBlockEntity chest&&chest.getItem(0).getCount()==3,"refused chest keeps three diamonds");world.setBlock(scene.contact(-5),Blocks.AIR.defaultBlockState(),3);retry(scene);STAGES[index]=4;continue;}
        if(stage==8){if(!root.blocked()||root.progress()!=0||NativeGearJournal.busy(root)||root.payload()==null||!root.payload().materialized())continue;for(var at:scene.platform(-1))need(world.getBlockState(at).is(Blocks.STONE_BRICKS),"new obstruction restores accessible native endpoint");need(world.getBlockState(scene.contact(-4)).is(Blocks.GOLD_BLOCK)&&world.getBlockState(scene.contact(-5)).is(Blocks.BEDROCK),"new obstruction retains already pushed terrain");world.setBlock(scene.contact(-5),Blocks.AIR.defaultBlockState(),3);retry(scene);STAGES[index]=4;continue;}
        if(stage==4){if(index==8&&!lateObstruction&&!NativeGearJournal.busy(root)&&root.progress()>0&&root.progress()<1&&world.getBlockState(scene.contact(-4)).is(Blocks.GOLD_BLOCK)){lateObstruction=true;world.setBlock(scene.contact(-5),Blocks.BEDROCK.defaultBlockState(),3);STAGES[index]=8;continue;}need(!root.blocked(),"outward push "+scene+" phase="+root.progress()+" "+root.error());if(root.progress()!=1||NativeGearJournal.busy(root)||root.payload()==null||!root.payload().materialized())continue;for(var at:scene.platform(-4))need(world.getBlockState(at).is(Blocks.STONE_BRICKS),"original layer advances three cells "+at);need(world.getBlockState(scene.contact(-5)).is(Blocks.GOLD_BLOCK),"contact advances only remaining cells");need(world.getBlockState(scene.contact(-6)).isAir(),"empty gap is not a pushed attachment");click(scene);STAGES[index]=5;continue;}
        if(stage==5){need(!root.blocked(),"push reversal "+scene+" "+root.error());if(root.progress()!=0||NativeGearJournal.busy(root)||root.payload()==null||!root.payload().materialized())continue;for(var at:scene.platform(-1))need(world.getBlockState(at).is(Blocks.STONE_BRICKS),"original native layer returns "+at);need(world.getBlockState(scene.contact(-5)).is(Blocks.GOLD_BLOCK),"contacted block stays behind");if(scene.layout!=0)need(world.getBlockState(scene.contact(scene.firstContact())).isAir(),"no duplicate contacted source");for(var column:scene.columns())need(world.getBlockState(column.relative(scene.mount.getOpposite())).is(Blocks.STONE),"mounting support retained");need(root.hasStoredSections(),"retracted native endpoint retains displaced sections separately");STAGES[index]=7;System.out.println("[vandorlabs][gear-push] case PASS index="+index+" "+scene);}
    }if(all){need(protectionProbe,"actual ARMED protection callback exercised");need(lateObstruction,"actual new midstroke obstruction exercised");finish("write");}}catch(Throwable failure){fail(failure);}}
    @SubscribeEvent(priority=net.neoforged.bus.api.EventPriority.LOWEST,receiveCanceled=true) public static void protection(net.neoforged.neoforge.event.level.BlockEvent.BreakEvent event){
        if(!running||protectionProbe||!phase().equals("write"))return;var own=NativeGearJournal.breakHoldExemption(event);if(own==null)return;protectionProbe=true;
        need(!event.isCanceled(),"exact admitted protection event remains usable");need(com.vandorlabs.neoforge.ramp.NativeRampHeldOwners.blocked(world,event.getPos()),"ordinary held-owner queries stay blocked during callbacks");
        var nested=new net.neoforged.neoforge.event.level.BlockEvent.BreakEvent(world,event.getPos(),event.getState(),actor);need(net.neoforged.neoforge.common.NeoForge.EVENT_BUS.post(nested).isCanceled(),"reentrant different break event remains blocked");
        var state=world.getBlockState(event.getPos());need(!world.setBlock(event.getPos(),Blocks.AIR.defaultBlockState(),18)&&world.getBlockState(event.getPos())==state,"reentrant terrain mutation remains blocked");
        var foreign=UUID.randomUUID();NativeGearHolds.freeze(world,foreign,List.of(event.getPos()));try{need(com.vandorlabs.neoforge.ramp.NativeRampHeldOwners.blockedForBreak(world,event.getPos(),own),"admitted event cannot bypass a foreign gear hold");}finally{NativeGearHolds.release(foreign);}
    }
    private static void finish(String marker){running=false;System.out.println("[vandorlabs][gear-push] "+marker+" PASS cases="+SCENES.size()+" checks="+checks+" SurvivalPlacement/regularLarge/fourHorizontalFaces/independentLineRectangle/fullPathRefusal/gapContact/reversal/restart");world.getServer().saveEverything(true,true,true);world.getServer().halt(false);}
    private static void fail(Throwable failure){running=false;failure.printStackTrace();System.out.println("[vandorlabs][gear-push] "+phase()+" FAIL "+failure);if(world!=null)world.getServer().halt(false);}
}
